-- One More Quest: boss loot seen in WoW Forever that the boss lists of Data/DungeonLoot.lua and
-- Data/ForeverDungeons.lua miss. Generated by tests/bossloot_gen.py from the loot measured in the game
-- (forever.warcraftdb.com, 2026-11-25): uncommon or better gear and recipes seen at least twice.
-- [npcID] = { itemID, ... }, added to that boss in every dungeon list
local ADDON, OMQ = ...
OMQ = _G.OneMoreQuest
local SEEN = {
    [3653] = { 3040 },
    [3673] = { 9768 },
    [3975] = { 274295 },
    [3976] = { 251398 },
    [5708] = { 10128 },
    [6487] = { 274294 },
    [7271] = { 274642 },
    [7272] = { 274639, 274641 },
    [7356] = { 274380 },
    [7604] = { 274646 },
    [7795] = { 274652 },
    [7796] = { 274645, 274643 },
    [8567] = { 274385 },
    [9568] = { 10214 },
    [9736] = { 16680, 16703, 16713 },
    [9816] = { 249520 },
    [10363] = { 10384, 10249 },
    [10596] = { 249521 },
    [11032] = { 276398 },
    [12203] = { 254106 },
    [14354] = { 18316 },
    [245999] = { 273034, 273035 },
    [246008] = { 273040, 273042 },
    [246016] = { 273044, 273043 },
    [246017] = { 273048, 273047 },
    [246020] = { 273049, 273051 },
    [247126] = { 273033, 273036 },
}
for _, bosses in pairs(OMQ.DungeonLoot or {}) do
    for _, boss in ipairs(bosses) do
        local more = SEEN[boss[1]]
        if more then
            local has = {}
            for i = 2, #boss do has[boss[i]] = true end
            for _, item in ipairs(more) do
                if not has[item] then boss[#boss + 1] = item; has[item] = true end
            end
        end
    end
end
